import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.text.*;import java.util.*;import javax.net.ssl.*;import org.json.*;

/** Direct mobile Edge voice catalogue and speech transport. No desktop dependency. */
public final class EdgeSpeech {
 static final String HOST="speech.platform.bing.com",BASE="/consumer/speech/synthesize/readaloud",TOKEN="6A5AA1D4EAFF4E9FB37E23D68491D6F4",VERSION="2-143.0.3650.75";
 static final String UA="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36 Edg/143.0.0.0";
 static final SecureRandom RANDOM=new SecureRandom();volatile long clockOffset=0;private volatile JSONArray cached=new JSONArray();final File cacheFile;
 public EdgeSpeech(File cache){cacheFile=cache;try{cached=new JSONArray(new String(bytes(new FileInputStream(cache),2*1024*1024),StandardCharsets.UTF_8));}catch(Exception ignored){}}
 public void seed(InputStream input)throws Exception{if(cached.length()==0)cached=new JSONArray(new String(bytes(input,2*1024*1024),StandardCharsets.UTF_8));else input.close();}
 public JSONArray cachedVoices(){JSONArray result=new JSONArray();for(int i=0;i<cached.length();i++)try{JSONObject v=cached.getJSONObject(i);result.put(new JSONObject().put("voiceURI","edge:"+v.getString("ShortName")).put("name","Edge 在线 · "+v.optString("FriendlyName",v.getString("ShortName"))).put("lang",v.optString("Locale","zh-CN")).put("source","edge-direct"));}catch(Exception ignored){}return result;}
 static byte[] bytes(InputStream input,int limit)throws IOException{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("语音响应过大");out.write(b,0,n);}return out.toByteArray();}}
 String token(){return EdgeToken.generate(System.currentTimeMillis()+clockOffset);}
 void adjust(String date){if(date==null)return;try{SimpleDateFormat f=new SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss z",Locale.US);f.setTimeZone(TimeZone.getTimeZone("GMT"));clockOffset=f.parse(date).getTime()-System.currentTimeMillis();}catch(Exception ignored){}}
 public synchronized JSONArray refresh()throws Exception{
  for(int attempt=0;attempt<2;attempt++){
   URL url=new URL("https://"+HOST+BASE+"/voices/list?trustedclienttoken="+TOKEN+"&Sec-MS-GEC="+token()+"&Sec-MS-GEC-Version="+VERSION);HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent",UA);c.setRequestProperty("Accept","*/*");c.setRequestProperty("Accept-Language","en-US,en;q=0.9");c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("Cookie","muid="+uuid().toUpperCase(Locale.ROOT)+";");
   try{int status=c.getResponseCode();if(status==403&&attempt==0){adjust(c.getHeaderField("Date"));continue;}if(status!=200)throw new IOException("在线音色服务返回 "+status);JSONArray list=new JSONArray(new String(bytes(c.getInputStream(),2*1024*1024),StandardCharsets.UTF_8));if(list.length()<1)throw new IOException("在线音色列表为空");cached=list;if(cacheFile!=null){File parent=cacheFile.getParentFile();if(parent!=null)parent.mkdirs();try(FileOutputStream out=new FileOutputStream(cacheFile)){out.write(list.toString().getBytes(StandardCharsets.UTF_8));}}return cachedVoices();}finally{c.disconnect();}
  }throw new IOException("无法刷新在线音色");
 }
 static String uuid(){return UUID.randomUUID().toString().replace("-","");}
 static String date(){SimpleDateFormat f=new SimpleDateFormat("EEE MMM dd yyyy HH:mm:ss 'GMT+0000 (Coordinated Universal Time)'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("GMT"));return f.format(new Date());}
 static String esc(String text){return text.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]"," ").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("'","&apos;").replace("\"","&quot;");}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){if(c=='\n')break;if(c!='\r')out.write(c);if(out.size()>16384)throw new IOException("响应头过大");}return out.toString("UTF-8");}
 static byte[] exact(InputStream in,int size)throws IOException{byte[] data=new byte[size];int read=0,n;while(read<size&&(n=in.read(data,read,size-read))!=-1)read+=n;if(read!=size)throw new EOFException("语音连接已关闭");return data;}
 static void send(OutputStream out,int opcode,byte[] data)throws IOException{out.write(128|opcode);if(data.length<126)out.write(128|data.length);else if(data.length<=65535){out.write(128|126);out.write(data.length>>>8);out.write(data.length);}else{out.write(128|127);for(int i=7;i>=0;i--)out.write((int)((long)data.length>>>(i*8))&255);}byte[] mask=new byte[4];RANDOM.nextBytes(mask);out.write(mask);byte[] payload=data.clone();for(int i=0;i<payload.length;i++)payload[i]^=mask[i%4];out.write(payload);out.flush();}
 static void text(OutputStream out,String data)throws IOException{send(out,1,data.getBytes(StandardCharsets.UTF_8));}
 public byte[] synthesize(String text,String voice,double rate)throws Exception{
  if(text==null||text.trim().isEmpty()||text.length()>1000)throw new IOException("一次朗读需为 1 至 1000 字");if(voice.startsWith("edge:"))voice=voice.substring(5);if(!voice.matches("[a-zA-Z0-9-]{3,100}"))throw new IOException("音色名称无效");
  for(int attempt=0;attempt<2;attempt++)try{return stream(text,voice,Math.max(.6,Math.min(2,rate)));}catch(HandshakeFailure error){if(error.status==403&&attempt==0){adjust(error.date);continue;}throw new IOException("在线语音连接失败（"+error.status+"），请检查网络或切换音色");}throw new IOException("在线语音连接失败");
 }
 static final class HandshakeFailure extends IOException{final int status;final String date;HandshakeFailure(int s,String d){status=s;date=d;}}
 byte[] stream(String phrase,String voice,double rate)throws Exception{
  Socket tcp=new Socket();tcp.connect(new InetSocketAddress(HOST,443),10000);try(SSLSocket socket=(SSLSocket)((SSLSocketFactory)SSLSocketFactory.getDefault()).createSocket(tcp,HOST,443,true)){
   socket.setSoTimeout(45000);SSLParameters parameters=socket.getSSLParameters();parameters.setEndpointIdentificationAlgorithm("HTTPS");parameters.setServerNames(Collections.singletonList(new SNIHostName(HOST)));socket.setSSLParameters(parameters);socket.startHandshake();InputStream in=new BufferedInputStream(socket.getInputStream());OutputStream out=socket.getOutputStream();byte[] nonce=new byte[16];RANDOM.nextBytes(nonce);String key=Base64.getEncoder().encodeToString(nonce);
   String url=BASE+"/edge/v1?TrustedClientToken="+TOKEN+"&ConnectionId="+uuid()+"&Sec-MS-GEC="+token()+"&Sec-MS-GEC-Version="+VERSION;
   out.write(("GET "+url+" HTTP/1.1\r\nHost: "+HOST+"\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: "+key+"\r\nSec-WebSocket-Version: 13\r\nOrigin: chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold\r\nUser-Agent: "+UA+"\r\nAccept-Language: en-US,en;q=0.9\r\nPragma: no-cache\r\nCache-Control: no-cache\r\nCookie: muid="+uuid().toUpperCase(Locale.ROOT)+";\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.flush();String statusLine=line(in);Map<String,String> headers=new HashMap<>();String header;while(!(header=line(in)).isEmpty()){int colon=header.indexOf(':');if(colon>0)headers.put(header.substring(0,colon).toLowerCase(Locale.ROOT),header.substring(colon+1).trim());}String[] statusParts=statusLine.split(" ");int status=statusParts.length>1?Integer.parseInt(statusParts[1]):0;if(status!=101)throw new HandshakeFailure(status,headers.get("date"));String expected=Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-1").digest((key+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII)));if(!expected.equals(headers.get("sec-websocket-accept")))throw new IOException("语音 WebSocket 握手校验失败");
   text(out,"X-Timestamp:"+date()+"\r\nContent-Type:application/json; charset=utf-8\r\nPath:speech.config\r\n\r\n{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":{\"sentenceBoundaryEnabled\":\"true\",\"wordBoundaryEnabled\":\"false\"},\"outputFormat\":\"audio-24khz-48kbitrate-mono-mp3\"}}}}\r\n");
   String percentage=String.format(Locale.ROOT,"%+d%%",Math.round((rate-1)*100));String ssml="<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='en-US'><voice name='"+voice+"'><prosody pitch='+0Hz' rate='"+percentage+"' volume='+0%'>"+esc(phrase)+"</prosody></voice></speak>";
   text(out,"X-RequestId:"+uuid()+"\r\nContent-Type:application/ssml+xml\r\nX-Timestamp:"+date()+"Z\r\nPath:ssml\r\n\r\n"+ssml);ByteArrayOutputStream audio=new ByteArrayOutputStream(),fragments=new ByteArrayOutputStream();int messageOpcode=0;long deadline=System.currentTimeMillis()+60000;
   while(System.currentTimeMillis()<deadline){int a=in.read(),b=in.read();if(a<0||b<0)throw new EOFException("在线语音连接中断");boolean fin=(a&128)!=0,masked=(b&128)!=0;int opcode=a&15;long size=b&127;if(size==126){byte[] n=exact(in,2);size=((n[0]&255)<<8)|(n[1]&255);}else if(size==127){size=0;for(byte n:exact(in,8))size=(size<<8)|(n&255);}if(size<0||size>4*1024*1024)throw new IOException("语音帧大小无效");byte[] mask=masked?exact(in,4):null;byte[] payload=exact(in,(int)size);if(mask!=null)for(int i=0;i<payload.length;i++)payload[i]^=mask[i%4];if(opcode==9){send(out,10,payload);continue;}if(opcode==10)continue;if(opcode==8)break;if(opcode!=0){messageOpcode=opcode;fragments.reset();}fragments.write(payload);if(fragments.size()>8*1024*1024)throw new IOException("语音消息过大");if(!fin)continue;byte[] data=fragments.toByteArray();fragments.reset();if(messageOpcode==1){String msg=new String(data,StandardCharsets.UTF_8);if(msg.contains("Path:turn.end"))break;}else if(messageOpcode==2&&data.length>=2){int headerLength=((data[0]&255)<<8)|(data[1]&255);if(headerLength+2>data.length)throw new IOException("语音音频帧格式无效");String meta=new String(data,2,headerLength,StandardCharsets.UTF_8);if(meta.contains("Path:audio")&&meta.contains("Content-Type:audio/mpeg"))audio.write(data,headerLength+2,data.length-headerLength-2);if(audio.size()>8*1024*1024)throw new IOException("语音音频过大");}}
   if(audio.size()<100)throw new IOException("在线音色未返回音频，请换音色或网络重试");return audio.toByteArray();
  }finally{try{tcp.close();}catch(Exception ignored){}}
 }
}
